affine_synthesis.py:
"""Constrained synthesis of single-target quadratic Boolean oracles."""

from functools import lru_cache
from itertools import combinations
import time

from .arithmetic import oracle_form
from .core import Gate, Proposal, cost


@lru_cache(maxsize=8)
def dictionary(n):
    """Index equivalent products by quadratic spectrum and linear correction."""
    pairs = tuple(combinations(range(n), 2))
    result = {}
    for left, right in combinations(range(1, 1 << n), 2):
        a_only, b_only = left & ~right, right & ~left
        if not a_only or not b_only:
            continue
        spectrum = sum(
            ((((left >> i) & (right >> j)) ^ ((left >> j) & (right >> i))) & 1) << k
            for k, (i, j) in enumerate(pairs)
        )
        # left*right over GF(2) contributes x_i^2 = x_i on overlap.
        key = spectrum, left & right
        rank = left.bit_count() + right.bit_count()
        if key not in result or rank < result[key][0]:
            result[key] = rank, left, right
    return pairs, tuple((spectrum, linear, left, right)
                        for (spectrum, linear), (_, left, right) in sorted(result.items()))


def product(wires, target, left, right):
    a = ((left & ~right) & -(left & ~right)).bit_length() - 1
    b = ((right & ~left) & -(right & ~left)).bit_length() - 1
    basis = [Gate("CX", (q, wires[pivot]))
             for mask, pivot in [(left, a), (right, b)]
             for i, q in enumerate(wires) if i != pivot and (mask >> i) & 1]
    return basis + [Gate("CCX", (*sorted((wires[a], wires[b])), target))] + basis[::-1]


def constrained_affine(gates, budget, seed):
    """Search increasing numbers of parity products, never gate selectors."""
    if cost(gates)[0] < 2:
        return None
    form = oracle_form(gates)
    if form is None:
        return None
    wires, terms, targets, _ = form
    if targets.bit_count() != 1:
        return None
    target_index = targets.bit_length() - 1
    inputs = [q for i, q in enumerate(wires) if i != target_index]
    if not 2 <= len(inputs) <= 5:
        return None
    try:
        import z3
    except ImportError:
        return Proposal(gates, {"solver_status": "UNAVAILABLE", "reason": "Install optional z3-solver"})

    def old_mask(mask):
        indices = [i for i in range(len(wires)) if i != target_index]
        return sum(1 << index for j, index in enumerate(indices) if (mask >> j) & 1)

    pairs, products = dictionary(len(inputs))
    expected = sum((old_mask((1 << i) | (1 << j)) in terms) << k
                   for k, (i, j) in enumerate(pairs))
    if not expected:
        return None
    linear = sum((old_mask(1 << i) in terms) << i for i in range(len(inputs)))
    target = wires[target_index]
    deadline = time.monotonic() + budget["seconds"]
    attempts = []
    for count in range(1, min(cost(gates)[0] - 1, budget["depth"]) + 1):
        left = deadline - time.monotonic()
        if left <= 0:
            return Proposal(gates, {"solver_status": "TIMEOUT", "attempts": attempts})
        solver = z3.Solver()
        solver.set(timeout=max(1, int(left * 1000)), rlimit=budget["max_states"] * 10,
                   random_seed=seed & 0x7fffffff)
        use = [z3.Bool(f"product_{i}") for i in range(len(products))]
        # Each product appears at most once. XOR terms have no ordering symmetry.
        solver.add(z3.PbEq([(v, 1) for v in use], count))
        for bit in range(len(pairs)):
            parity = z3.BoolVal(False)
            for variable, (spectrum, _, _, _) in zip(use, products):
                if (spectrum >> bit) & 1:
                    parity = z3.Xor(parity, variable)
            solver.add(parity == bool((expected >> bit) & 1))
        status = solver.check()
        reason = solver.reason_unknown() if status == z3.unknown else None
        label = "TIMEOUT" if reason == "timeout" else str(status).upper()
        attempts.append({"products": count, "status": label, "reason": reason})
        if status == z3.sat:
            model = solver.model()
            candidate = [Gate("X", (target,))] if 0 in terms else []
            for variable, (_, correction, left, right) in zip(use, products):
                if z3.is_true(model.eval(variable)):
                    candidate.extend(product(inputs, target, left, right))
                    linear ^= correction
            candidate.extend(Gate("CX", (wire, target))
                             for i, wire in enumerate(inputs) if (linear >> i) & 1)
            return Proposal(candidate, {"solver_status": "SAT", "attempts": attempts,
                                        "dictionary_size": len(products)})
        if status == z3.unknown:
            return Proposal(gates, {"solver_status": label, "attempts": attempts})
    return Proposal(gates, {"solver_status": "UNSAT", "attempts": attempts,
                            "scope": "bounded quadratic parity-product dictionary"})

arithmetic.py:
"""Exact Boolean arithmetic resynthesis using shared nonlinear terms."""

from .core import Gate, Proposal, REV, cost, signature

ARITHMETIC_OPS = {"X", "CX", "CCX", "SWAP", "CSWAP"}


def anf(table):
    """Vector-valued Möbius transform over GF(2)."""
    coefficients = list(table)
    for bit in range((len(table) - 1).bit_length()):
        for mask in range(len(table)):
            if mask & (1 << bit):
                coefficients[mask] ^= coefficients[mask ^ (1 << bit)]
    return coefficients


def oracle_form(gates):
    """Recognize y ^= f(x), including helper wires that are restored."""
    wires = sorted({wire for gate in gates for wire in gate.q})
    if len(wires) > 8 or any(gate.op not in REV for gate in gates):
        return None
    table = tuple(x ^ y for x, (y, _) in enumerate(signature(gates, wires)))
    terms = {mask: out for mask, out in enumerate(anf(table)) if out}
    modified = 0
    for out in terms.values():
        modified |= out
    # No target of the oracle may control another operation in its ANF.
    if any(mask & modified or mask.bit_count() > 2 for mask in terms):
        return None
    return wires, terms, modified, table


def selected(wires, mask):
    return [wire for i, wire in enumerate(wires) if (mask >> i) & 1]


def emit_terms(wires, terms, share=True):
    result = []
    for mask, target in sorted(terms.items()):
        controls = selected(wires, mask)
        targets = selected(wires, target)
        if len(controls) == 0:
            result.extend(Gate("X", (t,)) for t in targets)
        elif len(controls) == 1:
            result.extend(Gate("CX", (*controls, t)) for t in targets)
        elif len(controls) == 2 and share:
            pivot, *others = targets
            compute = [Gate("CX", (pivot, t)) for t in others]
            result.extend(compute + [Gate("CCX", (*controls, pivot))] + compute[::-1])
        elif len(controls) == 2:
            result.extend(Gate("CCX", (*controls, t)) for t in targets)
        else:
            raise ValueError("Oracle degree exceeds two")
    return result


def classify(wires, terms, modified, table):
    """Report only arithmetic families that match a full observed truth table.

    Layouts are small and inferred from sorted wire indices, in little-endian
    order. A fixed-point scale cannot be inferred from circuit dynamics.
    """
    outputs = [i for i in range(len(wires)) if (modified >> i) & 1]
    inputs_mask = 0
    for mask in terms:
        inputs_mask |= mask
    inputs = [i for i in range(len(wires)) if (inputs_mask >> i) & 1]
    if len(inputs) == 3 and len(outputs) == 1:
        if all(bool(table[x]) == (sum((x >> i) & 1 for i in inputs) >= 2)
               for x in range(len(table))):
            return "full_adder_carry"
    if len(inputs) and len(inputs) % 2 == 0 and outputs:
        size = len(inputs) // 2
        mask = (1 << len(outputs)) - 1

        def word(x, layout):
            return sum(((x >> i) & 1) << j for j, i in enumerate(layout))

        for name, fn in (("add_mod_power_of_two", lambda a, b: a+b),
                         ("subtract_mod_power_of_two", lambda a, b: a-b),
                         ("multiply_low_word", lambda a, b: a*b),
                         ("unsigned_less_than", lambda a, b: int(a < b))):
            if all(word(y, outputs) == fn(word(x, inputs[:size]), word(x, inputs[size:])) & mask
                   for x, y in enumerate(table)):
                return name
    return "quadratic_xor_oracle"


def two_bit_ripple(gates):
    """Detect in-place two-bit word addition and subtraction on either operand."""
    wires = sorted({wire for gate in gates for wire in gate.q})
    if len(wires) != 4 or any(gate.op not in REV for gate in gates):
        return None
    observed = signature(gates, wires)
    for inputs, outputs in ((wires[:2], wires[2:]), (wires[2:], wires[:2])):
        a0, a1 = inputs
        b0, b1 = outputs
        add = [Gate("CCX", (*sorted((a0, b0)), b1)), Gate("CX", (a1, b1)),
               Gate("CX", (a0, b0))]
        for family, candidate in (("in_place_add_2", add), ("in_place_subtract_2", add[::-1])):
            if cost(candidate) < cost(gates) and signature(candidate, wires) == observed:
                return Proposal(candidate, {"arithmetic_family": family,
                                            "architecture": "no_ancilla_ripple"})
    return None


def arithmetic_resynthesis(gates, budget, seed):
    """Try shared ANF and the factored majority architecture for a carry bit."""
    ripple = two_bit_ripple(gates)
    form = oracle_form(gates)
    if form is None:
        return ripple
    wires, terms, targets, table = form
    family = classify(wires, terms, targets, table)
    options = [("shared_anf", emit_terms(wires, terms)),
               ("direct_anf", emit_terms(wires, terms, share=False))]
    if family == "full_adder_carry":
        a, b, c = sorted({wire for mask in terms for wire in selected(wires, mask)})
        target, = selected(wires, targets)
        change_basis = [Gate("CX", (a, b)), Gate("CX", (a, c))]
        options.append(("majority_affine_sandwich", change_basis +
                        [Gate("CCX", (b, c, target)), Gate("CX", (a, target))] +
                        change_basis[::-1]))
    architecture, best = min(options, key=lambda item: cost(item[1]))
    if ripple and cost(ripple.gates) < cost(best):
        return ripple
    if cost(best) < cost(gates):
        return Proposal(best, {"arithmetic_family": family, "architecture": architecture,
                               "dirty_wire_contract": "arbitrary"})
    return None


def recycle_workspace(gates, budget, seed):
    """Eliminate compute/use/uncompute while retaining arbitrary helper value.

    For F toggling helper h, F·CX(h,t)·F equals CX(h,t) then toggle t by F's
    controls. The dirty input contribution survives exactly. A certified
    globally clean helper is required for actual wire removal.
    """
    for i, compute in enumerate(gates[:-2]):
        if compute.op != "CCX":
            continue
        a, b, helper = compute.q
        end = i + 1
        while end < len(gates):
            use = gates[end]
            if use.op != "CX" or use.q[0] != helper or use.q[1] in (a, b):
                break
            end += 1
        if end != i + 2 or end == len(gates) or gates[end] != compute:
            continue
        use = gates[i + 1]
        direct = Gate("CCX", (a, b, use.q[1]))
        candidate = gates[:i] + [use, direct] + gates[end + 1:]
        return Proposal(candidate, {"architecture": "dirty_workspace_uncompute_elision",
                                    "workspace": helper, "clean_ancilla_required": False})
    return None

circuit_io.py:
"""Project known operations into the engine while carrying opaque instructions through."""

from collections import Counter
from io import BytesIO
from pathlib import Path
import re
from tempfile import NamedTemporaryFile, TemporaryDirectory

from .core import parse, sha

QASM_HEADER = re.compile(r"\A(?:\s|//[^\n]*\n|/\*.*?\*/)*OPENQASM\s+([23])\b", re.S)


def detect_format(source, requested):
    if requested != "auto":
        return requested
    suffix = source.suffix.lower()
    if suffix in {".kmx", ".qpy"}:
        return suffix[1:]
    if suffix in {".qasm", ".qasm2", ".qasm3"}:
        match = QASM_HEADER.match(source.read_text(encoding="utf-8-sig"))
        if match:
            return "qasm" + match[1]
        if suffix != ".qasm":
            return suffix[1:]
    raise ValueError("Specify --input-format kmx, qpy, qasm2 or qasm3")


def load(source, kind, raw, index):
    from qiskit import QuantumCircuit, qasm2, qasm3, qpy

    if kind == "qpy":
        circuits = qpy.load(BytesIO(raw))
        if not 0 <= index < len(circuits):
            raise ValueError(f"QPY circuit index {index} out of range ({len(circuits)} circuits)")
        if not isinstance(circuits[index], QuantumCircuit):
            raise ValueError("The selected QPY entry must be a QuantumCircuit")
        return circuits[index]
    if index != 0:
        raise ValueError("--circuit-index applies to QPY bundles")
    if kind == "qasm2":
        # Includes resolve from the input file's directory and Qiskit's standard library.
        return qasm2.loads(raw.decode("utf-8-sig"), include_path=(source.parent,))
    return qasm3.loads(raw.decode("utf-8-sig"))


class CircuitProjection:
    def __init__(self, circuit, source_digest, index):
        from qiskit.circuit import library

        self.circuit = circuit
        self.gates = {
            name: getattr(library, cls) for name, cls in {
                "X": "XGate", "CX": "CXGate", "CCX": "CCXGate", "SWAP": "SwapGate",
                "CSWAP": "CSwapGate", "Z": "ZGate", "CZ": "CZGate", "CCZ": "CCZGate",
                "S": "SGate", "S_DAG": "SdgGate", "T": "TGate", "T_DAG": "TdgGate",
            }.items()
        }
        reverse = {cls: name for name, cls in self.gates.items()}
        self.header = f"QISKIT_SOURCE {source_digest} {index}"
        lines = [self.header]
        self.opaque = {}
        for position, item in enumerate(circuit.data):
            operation = item.operation
            name = reverse.get(operation.base_class)
            if (name and not item.clbits and operation.label is None
                    and getattr(operation, "condition", None) is None
                    and (not hasattr(operation, "ctrl_state")
                         or operation.ctrl_state == (1 << operation.num_ctrl_qubits) - 1)
                    and (not operation.mutable or operation.definition == self.gates[name]().definition)):
                qubits = [f"q{circuit.find_bit(bit).index}" for bit in item.qubits]
                lines.append(" ".join([name, *qubits]))
            else:
                self.opaque[position] = item
                lines.append(f"QISKIT_OPAQUE {position}")
        self.data = ("\n".join(lines) + "\n").encode("ascii")

    def restore(self, data):
        if data == self.data:
            return self.circuit
        lines = data.decode("ascii").splitlines()
        if not lines or lines[0] != self.header:
            raise ValueError("Circuit projection has the wrong source identity")
        result = self.circuit.copy_empty_like()
        carried = []
        for line in lines[1:]:
            if line.startswith("QISKIT_OPAQUE "):
                position = int(line.split()[1])
                result.append(self.opaque[position], copy=False)
                carried.append(position)
                continue
            gate = parse(line)
            if gate is None:
                raise ValueError(f"Invalid projected instruction {line!r}")
            result.append(self.gates[gate.op](), [result.qubits[i] for i in gate.q])
        if carried != list(self.opaque):
            raise ValueError("Opaque instruction sequence changed")
        return result

    def export(self, data, out):
        from qiskit import qpy

        result = self.restore(data)
        dest = out / "optimized.qpy"
        with NamedTemporaryFile(dir=out, delete=False) as stream:
            temp = Path(stream.name)
            try:
                qpy.dump(result, stream)
                stream.flush()
                temp.replace(dest)
            finally:
                temp.unlink(missing_ok=True)

        def describe(circuit):
            return {"operations": len(circuit.data), "depth": circuit.depth(),
                    "qubits": circuit.num_qubits, "classical_bits": circuit.num_clbits,
                    "operation_counts": dict(circuit.count_ops())}

        return {"output_circuit": str(dest), "output_format": "qpy",
                "input_metrics": describe(self.circuit), "output_metrics": describe(result),
                "preserved_opaque_operations": dict(Counter(item.operation.name for item in self.opaque.values()))}


def run_circuit(args, config, kind, executor):
    from qiskit.exceptions import QiskitError
    from types import SimpleNamespace

    source = Path(args.source)
    raw = source.read_bytes()
    digest = sha(raw)
    if args.expected_sha and digest != args.expected_sha:
        raise ValueError(f"BASELINE_SHA_MISMATCH {digest}")
    if source.is_relative_to(Path(args.out)):
        raise ValueError("Keep the immutable source outside the output directory")
    try:
        circuit = load(source, kind, raw, args.circuit_index)
        projection = CircuitProjection(circuit, digest, args.circuit_index)
        with TemporaryDirectory(prefix="optimizer-projection-") as temp:
            projected = Path(temp) / "projection.kmx"
            projected.write_bytes(projection.data)
            engine_args = SimpleNamespace(**{**vars(args), "source": str(projected),
                                           "expected_sha": sha(projection.data)})
            def export(data, out):
                return {**projection.export(data, out), "input_format": kind,
                        "original_source_sha256": digest, "circuit_index": args.circuit_index}

            return executor(engine_args, config, export=export)
    except QiskitError as exc:
        raise ValueError(f"{kind} circuit could not be processed: {exc}") from exc

core.py:
"""Fail-closed KMX subset and exact reversible/diagonal semantics.

Unsupported operations, inline conditions, and classical control are barriers.
Truth signatures compare every basis state including dirty ancillary wires.
Z_POW uses Kickmix unsigned 128-bit fixed-point turns.
"""
from dataclasses import dataclass
import hashlib
from fractions import Fraction
import re
import json
from collections import Counter

ARITY = {'X': 1, 'CX': 2, 'CCX': 3, 'SWAP': 2, 'CSWAP': 3,
         'Z': 1, 'CZ': 2, 'CCZ': 3, 'S': 1, 'S_DAG': 1, 'T': 1, 'T_DAG': 1}
REV = {'X', 'CX', 'CCX', 'SWAP', 'CSWAP'}
DIAG = set(ARITY) - REV
PHASE = {'Z': 4, 'CZ': 4, 'CCZ': 4, 'S': 2, 'S_DAG': -2, 'T': 1, 'T_DAG': -1}
TURN = 1 << 128
EIGHTH = TURN // 8
DECIMAL_ANGLE = re.compile(r"[+-]?[0-9]+\.[0-9]+", re.ASCII)

SCORED = {'CCX', 'CCZ', 'CSWAP'}

@dataclass(frozen=True)
class Gate:
    op: str
    q: tuple
    angle: int | None = None

    def text(self):
        angle = ''
        if self.angle is not None:
            # Decimal expansion of ticks / 2**127 in half turns.
            scaled = self.angle * 5**127
            whole, fraction = divmod(scaled, 10**127)
            angle = f" {whole}.{fraction:0127d}".rstrip("0")
            if angle.endswith("."):
                angle += "0"
        return self.op + ' ' + ' '.join(f'q{x}' for x in self.q) + angle + '\n'


def parse(line):
    tokens = line.split()
    if len(tokens) == 3 and tokens[0] == 'Z_POW':
        literal = tokens[2]
        if len(literal) > 260 or not DECIMAL_ANGLE.fullmatch(literal):
            return None
        target = parse('X ' + tokens[1])
        if target is None:
            return None
        return Gate('Z_POW', target.q, round(Fraction(literal) * (TURN // 2)) % TURN)
    if not tokens or tokens[0] not in ARITY or len(tokens) != ARITY[tokens[0]] + 1:
        return None
    if any(not q.startswith('q') or not q[1:].isascii() or not q[1:].isdigit() for q in tokens[1:]):
        return None
    q = tuple(int(x[1:]) for x in tokens[1:])
    if len(set(q)) != len(q):
        return None
    op = tokens[0]
    if op in {'CCX', 'CZ', 'CCZ', 'SWAP'}:
        q = tuple(sorted(q)) if op != 'CCX' else tuple(sorted(q[:2])) + q[2:]
    if op == 'CSWAP':
        q = q[:1] + tuple(sorted(q[1:]))
    return Gate(op, q)


def sha(data):
    return hashlib.sha256(data if isinstance(data, bytes) else data.encode()).hexdigest()


def signature(gates, wires):
    if len(wires) > 10:
        raise ValueError('exact table width exceeds 10')
    index = {q: i for i, q in enumerate(wires)}
    result = []
    for v in range(1 << len(wires)):
        phase = 0
        for gate in gates:
            q = [index[x] for x in gate.q]
            bits = [(v >> x) & 1 for x in q]
            if gate.op == 'X':
                v ^= 1 << q[0]
            elif gate.op == 'CX':
                v ^= bits[0] << q[1]
            elif gate.op == 'CCX':
                v ^= (bits[0] & bits[1]) << q[2]
            elif gate.op in {'SWAP', 'CSWAP'}:
                if gate.op == 'SWAP' or bits[0]:
                    if bits[-1] != bits[-2]:
                        v ^= (1 << q[-1]) | (1 << q[-2])
            elif gate.op in PHASE:
                if all(bits):
                    phase += PHASE[gate.op] * EIGHTH
            elif gate.op == 'Z_POW':
                phase += gate.angle * bits[0]
            else:
                raise ValueError('unsupported proof operation: ' + gate.op)
        result.append((v, phase % TURN))
    return tuple(result)


def prove(before, after, max_wires=10):
    wires = sorted({q for g in before + after for q in g.q})
    if len(wires) > max_wires:
        return {'status': 'UNPROVED_WIDTH_LIMIT', 'wires': len(wires)}
    equivalent = signature(before, wires) == signature(after, wires)
    return {'status': 'EXACT' if equivalent else 'REJECTED', 'wires': len(wires),
            'basis_states': 1 << len(wires), 'phase_modulus': TURN,
            'reference': sha(json.dumps(signature(before, wires)))}


def canonical(gates):
    mapping = {}
    normalized = []
    for g in gates:
        for q in g.q:
            mapping.setdefault(q, len(mapping))
        entry = (g.op, tuple(mapping[q] for q in g.q))
        normalized.append(entry if g.angle is None else (*entry, g.angle))
    return sha(json.dumps(normalized))


def cost(gates):
    c = Counter(g.op for g in gates)
    # Ranking proxy only. No claim of an official score estimate.
    return (sum(c[x] for x in SCORED), nonclifford(gates), len(gates))


def phase_ticks(gate):
    return gate.angle if gate.op == "Z_POW" else PHASE[gate.op] * EIGHTH


def nonclifford(gates):
    return sum(gate.op in {"T", "T_DAG"} or
               (gate.op == "Z_POW" and gate.angle % (2 * EIGHTH) != 0)
               for gate in gates)


def gate_from_record(record):
    return Gate(record["op"], tuple(record["q"]), record.get("angle"))


def census(lines):
    c = Counter(line.split()[0] for line in lines if line.split())
    return {'source_opcodes': dict(c), 'syntactically_unguarded_subset': dict(Counter(
        g.op for line in lines if (g := parse(line)) is not None)),
        'official_score': None, 'executed_toffoli': None, 'reaction_depth': None,
        'reason': 'Static counts cannot determine conditional execution or rotation synthesis precision.'}


def commute(a, b):
    if a is None or b is None:
        return False
    if set(a.q).isdisjoint(b.q):
        return True
    if (a.op in DIAG or a.op == 'Z_POW') and (b.op in DIAG or b.op == 'Z_POW'):
        return True
    if a.op in {'X', 'CX', 'CCX'} and b.op in {'X', 'CX', 'CCX'}:
        return a.q[-1] not in b.q[:-1] and b.q[-1] not in a.q[:-1]
    return False


@dataclass
class Proposal:
    gates: list
    detail: dict

model.py:
"""Receipt-calibrated Q*C model; estimates never confer correctness."""
import math


def estimate(metrics, delta_executed_toffoli=0, delta_qubits=0, delta_t=0,
             delta_rotations=0, rotation_t_cost=None):
    # Use the *measured* official aggregate, including all precision costs.
    if delta_rotations and rotation_t_cost is None:
        return {'status':'UNKNOWN','reason':'Rotation precision/headroom must be reverified'}
    q=metrics['num_qubits']+delta_qubits
    c=metrics['toffoli_equivalent']+delta_executed_toffoli+delta_t/4
    if delta_rotations: c+=delta_rotations*rotation_t_cost/4
    return {'status':'ESTIMATE','cost':q*c,'rotation_precision_unchanged':not delta_rotations,
            'reaction_depth_effect':'NOT_PRICED_UNTIL_OFFICIAL_SOURCE_CONFIRMS',
            'assumption':'Executed deltas must be measured or proved, not static source deltas'}


def calibrate(records, tolerance=1e-7):
    residuals=[]
    for m in records:
        predicted=m['num_qubits']*m['toffoli_equivalent']
        if not math.isfinite(predicted): raise ValueError('Nonfinite calibration')
        residuals.append(m['score']-predicted)
    maximum=max(map(abs,residuals),default=None)
    return {'samples':len(records),'max_absolute_residual':maximum,
            'status':'CALIBRATED_AGGREGATE_QC' if maximum is not None and maximum<=tolerance else 'UNCALIBRATED',
            'scope':'Aggregate identity only; not a dynamic execution/rotation precision predictor'}

